describe('Right-side Drawer Panel', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should open drawer panel from the right when trigger button is clicked', () => {
    cy.get('[data-testid="drawer-trigger"]').click();

    cy.get('[data-testid="drawer-panel"]')
      .should('be.visible')
      .should('have.class', 'drawer-open');

    cy.get('[data-testid="drawer-panel"]')
      .invoke('css', 'transform')
      .should('not.contain', 'translateX(100%)');

    cy.get('[data-testid="drawer-overlay"]')
      .should('be.visible')
      .should('have.css', 'opacity', '0.5');
  });

  it('should close drawer panel when close button is clicked', () => {
    cy.get('[data-testid="drawer-trigger"]').click();
    cy.get('[data-testid="drawer-panel"]').should('be.visible');

    cy.get('[data-testid="drawer-close"]').click();

    cy.get('[data-testid="drawer-panel"]')
      .should('not.be.visible')
      .should('not.have.class', 'drawer-open');
  });

  it('should close drawer when overlay is clicked', () => {
    cy.get('[data-testid="drawer-trigger"]').click();
    cy.get('[data-testid="drawer-panel"]').should('be.visible');

    cy.get('[data-testid="drawer-overlay"]').click({ force: true });

    cy.get('[data-testid="drawer-panel"]').should('not.be.visible');
  });

  it('should close drawer when Escape key is pressed', () => {
    cy.get('[data-testid="drawer-trigger"]').click();
    cy.get('[data-testid="drawer-panel"]').should('be.visible');

    cy.get('body').type('{esc}');

    cy.get('[data-testid="drawer-panel"]').should('not.be.visible');
  });

  it('should prevent body scroll when drawer is open', () => {
    cy.get('body').should('not.have.class', 'drawer-open-no-scroll');

    cy.get('[data-testid="drawer-trigger"]').click();
    cy.get('[data-testid="drawer-panel"]').should('be.visible');

    cy.get('body').should('have.class', 'drawer-open-no-scroll');

    cy.get('[data-testid="drawer-close"]').click();
    cy.get('body').should('not.have.class', 'drawer-open-no-scroll');
  });

  it('should render drawer content correctly', () => {
    cy.get('[data-testid="drawer-trigger"]').click();

    cy.get('[data-testid="drawer-panel"]').within(() => {
      cy.get('[data-testid="drawer-title"]')
        .should('be.visible')
        .should('contain', 'Drawer Title');

      cy.get('[data-testid="drawer-content"]')
        .should('be.visible')
        .should('contain.text', 'Drawer content goes here');
    });
  });

  it('should handle multiple open/close cycles', () => {
    for (let i = 0; i < 3; i++) {
      cy.get('[data-testid="drawer-trigger"]').click();
      cy.get('[data-testid="drawer-panel"]').should('be.visible');

      cy.get('[data-testid="drawer-close"]').click();
      cy.get('[data-testid="drawer-panel"]').should('not.be.visible');
    }
  });

  it('should maintain drawer position on right side of viewport', () => {
    cy.get('[data-testid="drawer-trigger"]').click();

    cy.get('[data-testid="drawer-panel"]').then(($drawer) => {
      const drawerRect = $drawer[0].getBoundingClientRect();
      const viewportWidth = window.innerWidth;

      expect(drawerRect.right).to.equal(viewportWidth);
      expect(drawerRect.left).to.be.greaterThan(viewportWidth / 2);
    });
  });
});
